mapper.select:
select vw.id, vw.create_user_id, vw.create_user_name, vw.create_time, vw.update_user_id, vw.update_user_name, vw.update_time, vw.disabled, vw.code, vw.name from virtual_warehouse vw where ${params.sqlMap.default} and vw.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
vw.id desc

SELECT id, name,code,disabled FROM virtual_warehouse WHERE is_deleted=false
and name in
#{name}

SELECT * from virtual_warehouse vw left join virtual_warehouse_relation vwr on vw.id = vwr.virtual_warehouse_id and vwr.is_deleted = false left join virtual_warehouse_channel vwc on vwc.virtual_warehouse_id = vw.id and vwc.is_deleted = false where vw.is_deleted = false
and ((vwc.type = 'shop' and vwc.dict_platform = #{params.dictPlatform} and vwc.relation_id = #{params.relationId}) or (vwc.type = 'platform' and vwc.dict_platform = #{params.dictPlatform}))
and vwc.type = 'platform' and vwc.dict_platform = #{params.dictPlatform}
and vwr.warehouse_id = #{params.warehouseId}
